// Markets tab: publicly traded AI-related companies + private AI unicorns.
// Data: data/markets.js (window.MARKETS), generated by tools/refresh-markets.py. Missing values render as a dash.
(function(){
const U = window.U, esc = U.esc;
function boot(M){
const el = () => document.getElementById('v-markets');
if(!M){ return; }
const SEGS = Object.keys(M.segments), TIERS = M.tiers;
const PER = M.periods || [{key:'1y', label:'1Y', days:365}];
const PKEYS = PER.map(p => p.key);
const SEG_SHORT = {chips:'Chips & semis', infra:'Infra, cloud & power', software:'Software & platforms', consumer:'Consumer & internet', robotics:'Robotics & autonomy', other:'Other'};
const q = new URLSearchParams(location.search);
const st = {
  seg: new Set(q.has('mseg') ? q.get('mseg').split(',').filter(s => SEGS.includes(s)) : SEGS),
  tier: new Set(q.has('mtier') ? q.get('mtier').split(',').map(t => TIERS[+t]).filter(Boolean) : TIERS),
  group: q.get('mgroup') === 'seg' ? 'seg' : 'tier',
  sort: ['cap','day','name','price',...PKEYS].includes(q.get('msort')) ? q.get('msort') : 'cap',
  dir: q.get('mdir') === 'asc' ? 1 : -1,
  per: PKEYS.includes(q.get('mper')) ? q.get('mper') : PKEYS[PKEYS.length - 1],
  find: ''
};
const DASH = '<span class="mut">—</span>';
const num = (v, d = 2) => v == null ? DASH : v.toLocaleString('en-US', {minimumFractionDigits: d, maximumFractionDigits: d});
const pct = v0 => { if(v0 == null) return DASH; const v = Math.abs(v0) < 0.05 ? 0 : v0; return `<span class="dl ${v > 0 ? 'up' : v < 0 ? 'down' : ''}">${v > 0 ? '+' : ''}${v.toFixed(Math.abs(v) >= 100 ? 0 : 1)}%</span>`; };
const cap = v => v == null ? DASH : v >= 1e12 ? `$${(v/1e12).toFixed(2)}T` : v >= 1e9 ? `$${(v/1e9).toFixed(v >= 1e11 ? 0 : 1)}B` : `$${(v/1e6).toFixed(0)}M`;
const capTitle = r => r.cap == null ? 'Market cap not available from the source' :
  `Reported market cap ${r.capCcy && r.capCcy !== 'USD' ? `${(r.capLocal/1e9).toLocaleString('en-US',{maximumFractionDigits:0})}B ${r.capCcy} → USD at the fetched FX rate` : ''} · as of ${r.capDate || 'unknown date'}`;
const price = r => r.price == null ? DASH : `${num(r.price, r.price < 1 ? 3 : (r.ccy && r.ccy !== 'USD' && r.price >= 1000) ? 0 : 2)}${r.ccy && r.ccy !== 'USD' ? ` <span class="d">${esc(r.ccy)}</span>` : ''}`;
// Numeric sorts: st.dir -1 = high to low; missing values (dash) always sort last. Name sorts A–Z (dir flips it).
const val = (r, k) => k === 'cap' ? r.cap : k === 'price' ? null : r[k];
const sortFn = () => { const k = st.sort, d = st.dir;
  if(k === 'name') return (a,b) => -d * (a.name || a.t).localeCompare(b.name || b.t);
  return (a,b) => { const va = val(a,k), vb = val(b,k); if(va == null && vb == null) return (b.cap ?? -1) - (a.cap ?? -1); if(va == null) return 1; if(vb == null) return -1; return d === -1 ? vb - va : va - vb; }; };
const perTitle = (r, p) => r[p.key] == null ? `${p.label}: not available (history shorter than ${p.days} days or no close near the lookback date)` : `${p.label} change since ${(r.base || {})[p.key] || 'lookback close'} close (${p.days}-day lookback)`;
const TIP = 'Click to toggle · Alt/Option-click or double-click to show only this one';
const chipRow = (kind, keys, label) => `<div class="tgroup"><span class="tl" id="mk-${kind}-l">${label}</span>
  <span class="qsel" role="group" aria-label="Quick select ${label.toLowerCase()}"><button type="button" class="qbtn" data-mqall="${kind}" title="Select all">All</button><button type="button" class="qbtn" data-mqnone="${kind}" title="Clear all">None</button></span>
  <div class="chips" role="group" aria-labelledby="mk-${kind}-l">${keys.map(k => `<button type="button" class="chip" data-m${kind}="${esc(k)}" title="${TIP}">${esc(kind === 'seg' ? SEG_SHORT[k] : k)} <span class="cnt">${M.rows.filter(r => kind === 'seg' ? r.seg === k : r.tier === k).length}</span></button>`).join('')}</div></div>`;

function rowsHtml(list){
  return list.map(r => `<tr${r.note ? ` title="${esc(r.note)}"` : ''}>
    <td data-l="Ticker"><a class="tk" href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.t)}</a></td>
    <td data-l="Company" class="nm"${r.name ? ` title="${esc(r.name + (r.note ? " - " + r.note : ""))}"` : ""}>${r.name ? esc(r.name) : DASH}${r.note ? ' <span class="d" aria-hidden="true">ⓘ</span>' : ''}</td>
    <td data-l="Segment"><span class="mseg s-${r.seg}">${esc(SEG_SHORT[r.seg])}</span></td>
    <td class="r" data-l="Price"${r.ccy && r.ccy !== 'USD' && r.pUsd ? ` title="≈ $${r.pUsd.toFixed(2)} USD at Yahoo FX"` : ''}>${price(r)}</td>
    <td class="r" data-l="Day">${pct(r.day)}</td>
    <td class="r" data-l="Market cap" title="${esc(capTitle(r))}">${cap(r.cap)}</td>
    ${PER.map(p => `<td class="r pc p-${p.key}${p.key === st.per ? ' psel' : ''}" data-l="${p.label}" title="${esc(perTitle(r, p))}">${pct(r[p.key])}</td>`).join('')}
    <td data-l="Quote"><a href="${esc(r.url)}" target="_blank" rel="noopener" aria-label="${esc(r.t)} quote on Yahoo Finance">Quote ↗</a></td></tr>`).join('');
}
const sh = (k, label, cls = '', tip = '') => { const on = st.sort === k, arrow = on ? (st.dir === -1 ? (k === 'name' ? ' ▲' : ' ▼') : (k === 'name' ? ' ▼' : ' ▲')) : '';
  return `<th class="${cls}" aria-sort="${on ? ((st.dir === -1) === (k !== 'name') ? 'descending' : 'ascending') : 'none'}"${tip ? ` title="${esc(tip)}"` : ''}><button type="button" class="sorth msort" data-msort="${k}">${esc(label)}${arrow}</button></th>`; };
function table(){
  const f = st.find.trim().toLowerCase();
  const list = M.rows.filter(r => st.seg.has(r.seg) && (r.tier ? st.tier.has(r.tier) : st.tier.size === TIERS.length) && (!f || r.t.toLowerCase().includes(f) || (r.name || '').toLowerCase().includes(f))).sort(sortFn());
  const groups = st.group === 'tier' ? [...TIERS, null].map(t => [t ? `Market cap ${t}` : 'Market cap unknown', list.filter(r => r.tier === t)])
                                     : SEGS.map(s => [M.segments[s], list.filter(r => r.seg === s)]);
  const body = groups.filter(([, l]) => l.length).map(([h, l]) => `<tbody><tr class="grp"><th colspan="${7 + PER.length}">${esc(h)} <span class="d">· ${l.length}</span></th></tr>${rowsHtml(l)}</tbody>`).join('');
  return {n: list.length, html: list.length ? `<table class="mkt per-${st.per}"><thead><tr><th>Ticker</th>${sh('name','Company')}<th>Segment</th><th class="r">Price</th>${sh('day','Day','r')}${sh('cap','Market cap','r')}${PER.map(p => sh(p.key, p.label, `r pc p-${p.key}${p.key === st.per ? ' psel' : ''}`, `${p.label} = change vs the close nearest ${p.days} days ago`)).join('')}<th>Link</th></tr></thead>${body}</table>`
    : `<div class="note" style="padding:10px">No companies match these filters. <button type="button" class="qbtn" data-mreset>Show all</button></div>`};
}
const unicorns = () => `<table class="mkt uni"><thead><tr><th>Company</th><th>What</th><th class="r">Latest reported valuation</th><th>Date</th><th>Status</th><th>Source</th></tr></thead><tbody>
  ${[...M.unicorns].sort((a,b) => (b.valuation_usd ?? 0) - (a.valuation_usd ?? 0)).map(u => `<tr>
    <td data-l="Company"><b>${esc(u.name)}</b></td><td data-l="What">${esc(u.what)}</td>
    <td class="r" data-l="Valuation"><b>${cap(u.valuation_usd)}</b><div class="d">${esc(u.valuation_text)}</div></td>
    <td data-l="Date">${esc(u.date.length === 7 ? new Date(u.date + '-01T12:00').toLocaleDateString('en-US',{month:'short',year:'numeric'}) : U.fmtD(u.date))}</td>
    <td data-l="Status"><span class="priv">PRIVATE · NOT TRADABLE</span><div class="d">${esc(u.status)}</div></td>
    <td data-l="Source"><a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.source)} ↗</a></td></tr>`).join('')}</tbody></table>`;

function summary(){
  const cell = (lbl, n) => `<div class="mstat"><b>${n}</b><span>${esc(lbl)}</span></div>`;
  return `<div class="mstats">${TIERS.map(t => cell(t, M.rows.filter(r => r.tier === t).length)).join('')}</div>`;
}
function syncChips(root){
  ['seg','tier'].forEach(k => {
    root.querySelectorAll(`[data-m${k}]`).forEach(b => { const on = st[k].has(b.dataset['m' + k]); b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); });
    const total = k === 'seg' ? SEGS.length : TIERS.length;
    root.querySelectorAll(`[data-mqall="${k}"]`).forEach(b => b.setAttribute('aria-disabled', st[k].size === total));
    root.querySelectorAll(`[data-mqnone="${k}"]`).forEach(b => b.setAttribute('aria-disabled', st[k].size === 0));
  });
}
function renderTable(){
  const root = el(), t = table();
  root.querySelector('#mk-table').innerHTML = t.html;
  root.querySelector('#mk-count').textContent = `${t.n} of ${M.rows.length} companies`;
  root.querySelector('#mk-sort').value = st.sort;
  root.querySelectorAll('#mk-per button').forEach(b => { const on = b.dataset.per === st.per; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); });
  root.querySelectorAll('[data-msort]').forEach(b => b.onclick = () => { const k = b.dataset.msort; if(st.sort === k) st.dir *= -1; else { st.sort = k; st.dir = -1; } if(PKEYS.includes(k)) st.per = k; renderTable(); });
  syncChips(root);
}
function render(){
  const root = el(); if(!root) return;
  const asOf = M.pricesAsOfLabel || M.asOfLabel;
  root.innerHTML = `<h2>Markets · AI stocks</h2>
   <div class="sub">${M.rows.length} publicly traded AI-related companies (US and major foreign listings), grouped by market-cap tier, plus private AI unicorns. Each company sits in one primary segment.</div>
   <div class="caveat" role="note"><b>Not investment advice. Prices may be delayed.</b> <span id="mk-live" class="mklive" aria-live="polite">Snapshot · as of ${esc(asOf)}</span><br>Price and Day: live from Yahoo Finance via /api/quotes when available (cached ~60s), otherwise the daily snapshot. Snapshot source: ${esc(M.source)}; fetched ${esc(M.asOfLabel)}. Market caps are the source's latest reported values, converted to USD for non-US listings; 7D / 1M / 3M / 6M / 1Y = change from the daily close nearest 7, 30, 90, 180 and 365 days back to the latest price (dash if the history is shorter); click a column header to sort. A dash means the value could not be fetched.</div>
   ${summary()}
   <div class="toolbar">${chipRow('seg', SEGS, 'Segment')}</div>
   <div class="toolbar">${chipRow('tier', TIERS, 'Market cap')}</div>
   <div class="toolbar">
     <div class="tgroup"><span class="tl">Group</span><div class="seg2" id="mk-group"><button type="button" data-g="tier" class="${st.group==='tier'?'on':''}">By tier</button><button type="button" data-g="seg" class="${st.group==='seg'?'on':''}">By segment</button></div></div>
     <div class="tgroup"><label class="tl" for="mk-sort">Sort</label><select id="mk-sort"><option value="cap">Market cap</option><option value="day">Day change</option>${PER.map(p => `<option value="${p.key}">${p.label} change</option>`).join('')}<option value="name">Name A–Z</option></select></div>
     <div class="tgroup"><label class="tl" for="mk-find">Find</label><input id="mk-find" type="search" placeholder="Ticker or name" autocomplete="off"></div>
     <div class="tgroup mk-perg"><span class="tl" id="mk-per-l">Period</span><div class="seg2" id="mk-per" role="group" aria-labelledby="mk-per-l">${PER.map(p => `<button type="button" data-per="${p.key}" title="Show the ${p.label} change column">${p.label}</button>`).join('')}</div></div>
     <span class="d" id="mk-count" aria-live="polite"></span>
   </div>
   <div class="tblwrap mk-wrap" id="mk-table"></div>
   <!-- SPONSOR SLOT: reserved for a possible future sponsor/affiliate block. Intentionally empty and hidden; no affiliate links. -->
   <div id="mk-sponsor" class="sponsor-slot" data-slot="sponsor" hidden aria-hidden="true"></div>
   <h3 class="h3" style="margin-top:14px">AI unicorns · private, valued above $1B</h3>
   <div class="gapnote"><b>Private companies, not tradable on public exchanges.</b> Valuations are the latest reported funding-round or transaction figures with their date and source; they are not live prices. ${M.unicornNotes.map(esc).join(' ')}</div>
   <div class="tblwrap mk-wrap">${unicorns()}</div>
   <div class="d" style="margin-top:6px">Refresh: <code>python3 tools/refresh-markets.py</code> rebuilds data/markets.js; unicorn rows are curated by hand in tools/markets-universe.json.</div>`;
  root.querySelector('#mk-sort').value = st.sort;
  root.querySelector('#mk-sort').onchange = e => { st.sort = e.target.value; st.dir = -1; if(PKEYS.includes(st.sort)) st.per = st.sort; renderTable(); };
  root.querySelectorAll('#mk-per button').forEach(b => b.onclick = () => { st.per = b.dataset.per; if(PKEYS.includes(st.sort)) st.sort = st.per; renderTable(); });
  root.querySelector('#mk-find').oninput = e => { st.find = e.target.value; renderTable(); };
  root.querySelectorAll('#mk-group button').forEach(b => b.onclick = () => { st.group = b.dataset.g; root.querySelectorAll('#mk-group button').forEach(x => x.classList.toggle('on', x === b)); renderTable(); });
  ['seg','tier'].forEach(k => {
    const all = k === 'seg' ? SEGS : TIERS;
    root.querySelectorAll(`[data-m${k}]`).forEach(b => { const v = b.dataset['m' + k];
      const solo = () => { st[k] = new Set([v]); renderTable(); };
      b.onclick = e => { if(e.altKey){ e.preventDefault(); return solo(); } st[k].has(v) ? st[k].delete(v) : st[k].add(v); renderTable(); };
      b.ondblclick = e => { e.preventDefault(); solo(); };
      b.onkeydown = e => { if(e.altKey && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); solo(); } };
    });
    root.querySelectorAll(`[data-mqall="${k}"]`).forEach(b => b.onclick = () => { st[k] = new Set(all); renderTable(); });
    root.querySelectorAll(`[data-mqnone="${k}"]`).forEach(b => b.onclick = () => { st[k] = new Set(); renderTable(); });
  });
  root.querySelector('#mk-table').addEventListener('click', e => { if(e.target.closest('[data-mreset]')){ st.seg = new Set(SEGS); st.tier = new Set(TIERS); st.find = ''; root.querySelector('#mk-find').value = ''; renderTable(); } });
  renderTable();
}
// ---------- Live quotes (price + day % only; 7D–1Y stay from the daily snapshot) ----------
const ETF = new Intl.DateTimeFormat('en-US', {timeZone: 'America/New_York', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'});
const etParts = d => Object.fromEntries(ETF.formatToParts(d).map(p => [p.type, p.value]));
const marketOpen = (d = new Date()) => { const p = etParts(d), m = (+p.hour) * 60 + (+p.minute); return !['Sat','Sun'].includes(p.weekday) && m >= 570 && m < 960; };   // 9:30–16:00 ET, weekdays (exchange holidays not modelled)
const etTime = ts => new Date(ts * 1000).toLocaleTimeString('en-US', {timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit'}) + ' ET';
const etDateTime = ts => new Date(ts * 1000).toLocaleString('en-US', {timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'}) + ' ET';
let liveTimer = null, liveBusy = false;
async function live(){
  if(liveBusy || document.hidden) return; liveBusy = true;
  try {
    const ctl = new AbortController(), to = setTimeout(() => ctl.abort(), 6000);
    const r = await fetch('/api/quotes', {signal: ctl.signal, headers: {'Accept': 'application/json'}}); clearTimeout(to);
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const j = await r.json(); if(!j || !j.quotes || !j.count) throw new Error('empty');
    let n = 0; M.rows.forEach(row => { const q = j.quotes[row.t]; if(!q || q.p == null) return; row.price = q.p; if(q.d != null) row.day = q.d; row.pUsd = q.pUsd; row.live = true; n++; });
    if(!n) return;
    const open = marketOpen(), t = j.usLastTradeTime;
    const lbl = document.getElementById('mk-live');
    if(lbl){ lbl.textContent = open ? `Live · delayed ~1 min · updated ${etTime(t || Date.parse(j.fetchedAt) / 1000)}` : `Market closed · as of ${t ? etDateTime(t) : 'last close'}`; lbl.classList.toggle('on', open); }
    if(el() && el().querySelector('#mk-table')) renderTable();
  } catch(e) { /* silent fallback: keep the daily snapshot already on screen */ }
  finally { liveBusy = false; }
}
function startLive(){
  if(location.protocol === 'file:') return;          // opened from disk: snapshot only
  live();                                            // one fetch always
  clearInterval(liveTimer);
  liveTimer = setInterval(() => { if(marketOpen()) live(); }, 60000);   // poll only during US market hours
  document.addEventListener('visibilitychange', () => { if(!document.hidden && marketOpen()) live(); });
}
window.MK = {render, state: st, live, marketOpen};
render();
startLive();
}

// ---------- Sign in with X gate ----------
// Markets data (snapshot + live quotes) is served only to signed-in users by /api/markets and /api/quotes.
// Note: the snapshot file data/markets.js is also in the public GitHub repo, so the gate is a site feature, not secrecy.
const view = () => document.getElementById('v-markets');
const AUTH = {configured: false, signedIn: false, user: null};
const AUTH_MSG = {denied: 'Sign-in was cancelled on X.', state: 'Sign-in expired or was interrupted. Please try again.', token: 'X did not accept the sign-in. Please try again.', profile: 'Could not read your X profile. Please try again.', error: 'Sign-in failed. Please try again.', unavailable: 'Sign-in is not available yet.'};
const loginHref = () => '/api/auth/x/login?return=' + encodeURIComponent('/?v=markets');
function header(){
  const box = document.getElementById('authbox'); if(!box) return;
  if(AUTH.signedIn && AUTH.user){
    const hasHandle = AUTH.user.profile !== false && AUTH.user.username;
    const label = hasHandle ? `@${esc(AUTH.user.username)}` : 'Signed in with X';
    box.innerHTML = `<span class="who" title="${esc(AUTH.user.name || 'X user')}">${label}</span><a href="/api/auth/logout" class="so">Sign out</a>`;
  }
  else if(AUTH.configured) box.innerHTML = `<a href="${loginHref()}" class="si">Sign in with X</a>`;
  else box.innerHTML = '';
}
function teaser(){
  const v = view(); if(!v) return;
  const err = AUTH_MSG[new URLSearchParams(location.search).get('auth')];
  const bars = Array.from({length: 12}, (_, i) => `<tr>${[44, 150, 90, 60, 44, 60, 40, 40, 40, 40, 40].map(w => `<td><i style="width:${w - (i * 7) % 15}px"></i></td>`).join('')}</tr>`).join('');
  v.innerHTML = `<h2>Markets · AI stocks</h2>
   <div class="sub">Publicly traded AI-related companies by segment and market-cap tier, with live prices during US market hours and 7D–1Y changes, plus private AI unicorns.</div>
   <div class="mkgate">
     <div class="mkblur" aria-hidden="true"><table class="mkt"><thead><tr><th>Ticker</th><th>Company</th><th>Segment</th><th>Price</th><th>Day</th><th>Market cap</th><th>7D</th><th>1M</th><th>3M</th><th>6M</th><th>1Y</th></tr></thead><tbody>${bars}</tbody></table></div>
     <div class="mkgate-cta" role="region" aria-label="Sign in required">
       ${AUTH.configured ? `<a class="xbtn" href="${loginHref()}"><svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path fill="currentColor" d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg> Sign in with X to view Markets</a>`
         : `<span class="xbtn off" aria-disabled="true">Sign-in coming soon</span>`}
       ${err ? `<div class="mkerr" role="alert">${esc(err)}</div>` : ''}
       <div class="d">${AUTH.configured ? 'Free. Uses read-only access to your public X profile (users.read, tweet.read). Nothing is ever posted.' : 'Markets will open to signed-in X users soon.'} Not investment advice.</div>
     </div>
   </div>`;
}
async function getJSON(url, ms){
  const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), ms);
  try { const r = await fetch(url, {credentials: 'same-origin', cache: 'no-store', signal: ctl.signal, headers: {'Accept': 'application/json'}}); return r.ok ? await r.json() : null; }
  catch(e){ return null; } finally { clearTimeout(t); }
}
async function init(){
  if(location.protocol === 'file:'){   // opened from disk: load the local snapshot, no sign-in
    const sc = document.createElement('script'); sc.src = 'data/markets.js'; sc.onload = () => window.MARKETS && boot(window.MARKETS); document.head.appendChild(sc); return;
  }
  const me = await getJSON('/api/auth/me', 5000);
  if(me){ AUTH.configured = !!me.configured; AUTH.signedIn = !!me.signedIn; AUTH.user = me.user; }
  header();
  if(!AUTH.signedIn) return teaser();
  const snap = await getJSON('/api/markets', 8000);
  if(snap && snap.rows) boot(snap); else teaser();
}
window.MKAUTH = AUTH;
init();
})();
